//! Nested byte constants through the real object/link/native path. Expected
//! bytes are independent C literals, not generated by the initializer renderer.
//! Body fixtures have no unspecified padding; globals additionally check every
//! padding byte and a neighboring relocation. This is execution evidence only,
//! on AArch64 Linux GNU (ELF) and macOS (Mach-O).

#![cfg(all(
    target_arch = "aarch64",
    any(target_os = "macos", all(target_os = "linux", target_env = "gnu"))
))]

#[path = "common/rosetta.rs"]
mod process;

#[path = "common/native_host.rs"]
mod native_host;

#[path = "common/fresh_dir.rs"]
mod fresh_dir;

use std::fs;
use std::path::Path;
use std::process::Command;
use trust_cg_codegen::{Compiler, CompilerConfig, pipeline::OptLevel, target::TargetSpec};
use trust_ir::value::GlobalId;
use trust_ir::{
    Block, BlockId, Constant, Endianness, EnumDef, EnumId, EnumLayoutDescriptor, EnumTagEncoding,
    EnumTagRepr, EnumVariant, FieldDef, FuncId, FuncTy, Function, Global, Inst, InstrNode, Linkage,
    Module, StructDef, StructId, StructPassingPolicy, StructRepr, TargetInfo, Ty, ValueId,
};

const LEVELS: [OptLevel; 4] = [OptLevel::O0, OptLevel::O1, OptLevel::O2, OptLevel::O3];

fn bytes(data: &[u8], utf8: bool) -> Constant {
    Constant::Bytes {
        data: data.to_vec(),
        utf8,
    }
}

fn aggregate(values: impl IntoIterator<Item = Constant>) -> Constant {
    Constant::Aggregate(values.into_iter().collect())
}

fn base() -> Module {
    let mut module = Module::new("linux_nested_bytes");
    module.target_info = Some(TargetInfo {
        triple: native_host::TRIPLE.into(),
        pointer_size: 8,
        endianness: Endianness::Little,
        abi: Some("aapcs64".into()),
        struct_passing: StructPassingPolicy::NativeC,
    });
    module
}

fn byte_array(module: &mut Module, length: u64) -> Ty {
    Ty::Array(
        module
            .add_type(Ty::U8)
            .expect("Module::add_type: test fixture"),
        length,
    )
}

fn structure(
    module: &mut Module,
    name: &str,
    size: u64,
    align: u64,
    repr: StructRepr,
    fields: Vec<(&str, Ty, u64)>,
) -> Ty {
    let id = StructId::new(module.structs.len() as u32);
    module.structs.push(StructDef {
        id,
        name: name.into(),
        origin: None,
        size: Some(size),
        align: Some(align),
        repr,
        fields: fields
            .into_iter()
            .map(|(name, ty, offset)| FieldDef {
                name: name.into(),
                ty,
                offset: Some(offset),
            })
            .collect(),
    });
    Ty::Struct(id)
}

fn writer(module: &mut Module, ty: Ty, value: Constant) {
    let signature = module
        .add_func_type(FuncTy {
            params: vec![Ty::Ptr],
            returns: vec![],
            abi: None,
            is_vararg: false,
        })
        .expect("Module::add_func_type: test fixture");
    let mut function = Function::new(FuncId::new(0), "cg_write", signature, BlockId::new(0));
    function.linkage = Linkage::External;
    function.blocks = vec![Block {
        id: BlockId::new(0),
        params: vec![(ValueId::new(0), Ty::Ptr)],
        body: vec![
            InstrNode::new(Inst::Const {
                ty: ty.clone(),
                value,
            })
            .with_result(ValueId::new(1)),
            InstrNode::new(Inst::Store {
                ty,
                ptr: ValueId::new(0),
                value: ValueId::new(1),
                align: Some(1),
                volatile: false,
            }),
            InstrNode::new(Inst::Return { values: vec![] }),
        ],
    }];
    module
        .try_add_function(function)
        .expect("Module::try_add_function: test fixture");
}

fn direct_enum(module: &mut Module) -> Ty {
    let payload = byte_array(module, 3);
    module.enums.push(EnumDef {
        origin: None,
        id: EnumId::new(0),
        name: "DirectBytes".into(),
        variants: ["First", "Second"]
            .into_iter()
            .map(|name| EnumVariant {
                name: name.into(),
                fields: vec![payload.clone(), Ty::U8],
                field_names: vec![],
            })
            .collect(),
        discriminants: vec![],
        repr: Some(EnumTagRepr::U8),
        layout: Some(EnumLayoutDescriptor {
            encoding: EnumTagEncoding::Direct { tag_offset: 0 },
            size: 5,
            align: 1,
            variant_field_offsets: vec![vec![1, 4], vec![1, 4]],
        }),
    });
    Ty::Enum(EnumId::new(0))
}

fn body_fixture(kind: &str) -> Module {
    let mut module = base();
    let (ty, value) = match kind {
        "tuple" => {
            let data = byte_array(&mut module, 3);
            let empty = byte_array(&mut module, 0);
            (
                Ty::Tuple(vec![Ty::U8, Ty::Tuple(vec![data, empty]), Ty::U8]),
                aggregate([
                    Constant::Int(0x51),
                    aggregate([bytes(&[0x00, 0x80, 0xff], false), bytes(&[], true)]),
                    Constant::Int(0x9a),
                ]),
            )
        }
        "array" => {
            let row = byte_array(&mut module, 3);
            let row_id = module
                .add_type(row)
                .expect("Module::add_type: test fixture");
            (
                Ty::Array(row_id, 2),
                Constant::Array(vec![
                    bytes(&[0x01, 0x00, 0xff], false),
                    bytes(&[0x80, 0x7a, 0x7f], false),
                ]),
            )
        }
        "packed" => {
            let data = byte_array(&mut module, 2);
            let empty = byte_array(&mut module, 0);
            let ty = structure(
                &mut module,
                "PackedBytes",
                6,
                1,
                StructRepr::Packed(1),
                vec![
                    ("lead", Ty::U8, 0),
                    ("bytes", data, 1),
                    ("word", Ty::U16, 3),
                    ("empty", empty, 5),
                    ("tail", Ty::U8, 5),
                ],
            );
            (
                ty,
                aggregate([
                    Constant::Int(0x29),
                    bytes(&[0x00, 0xfe], false),
                    Constant::Int(0xb17d),
                    bytes(&[], false),
                    Constant::Int(0xa6),
                ]),
            )
        }
        "enum" => (
            direct_enum(&mut module),
            aggregate([
                Constant::Int(1),
                bytes(&[0x00, 0xc3, 0xa9], true),
                Constant::Int(0xe7),
            ]),
        ),
        _ => panic!("unknown closed fixture {kind}"),
    };
    writer(&mut module, ty, value);
    module
}

fn global(name: &str, ty: Ty, initializer: Option<Constant>) -> Global {
    Global {
        section: None,
        visibility: trust_ir::Visibility::Default,
        retained: false,
        name: name.into(),
        ty,
        mutable: true,
        initializer,
        linkage: Linkage::External,
        tls: None,
        align: None,
    }
}

fn global_fixture() -> Module {
    let mut module = base();
    let three = byte_array(&mut module, 3);
    let pair = byte_array(&mut module, 2);
    let pair_id = module
        .add_type(pair)
        .expect("Module::add_type: test fixture");
    let empty = byte_array(&mut module, 0);
    let ty = structure(
        &mut module,
        "GlobalBytes",
        32,
        8,
        StructRepr::C,
        vec![
            ("lead", Ty::U8, 0),
            ("inner", Ty::Tuple(vec![three, Ty::U16]), 2),
            ("rows", Ty::Array(pair_id, 2), 8),
            ("pointer", Ty::Ptr, 16),
            ("empty", empty, 24),
            ("tail", Ty::U16, 24),
        ],
    );
    module.globals.push(global(
        "nested_bytes",
        ty,
        Some(aggregate([
            Constant::Int(0x19),
            aggregate([bytes(&[0xff, 0x00, 0x80], false), Constant::Int(0x4b2d)]),
            Constant::Array(vec![
                bytes(&[0x00, 0x81], false),
                bytes(&[0xfe, 0x7f], false),
            ]),
            Constant::SymbolAddr {
                symbol: "external_bytes".into(),
                addend: 3,
            },
            bytes(&[], true),
            Constant::Int(0xa153),
        ])),
    ));
    let external_ty = byte_array(&mut module, 9);
    module
        .globals
        .push(global("external_bytes", external_ty, None));
    let signature = module
        .add_func_type(FuncTy {
            params: vec![],
            returns: vec![Ty::Ptr],
            abi: None,
            is_vararg: false,
        })
        .expect("Module::add_func_type: test fixture");
    let mut function = Function::new(FuncId::new(0), "cg_address", signature, BlockId::new(0));
    function.linkage = Linkage::External;
    function.blocks = vec![Block {
        id: BlockId::new(0),
        params: vec![],
        body: vec![
            InstrNode::new(Inst::GlobalAddr {
                global: GlobalId::new(0),
            })
            .with_result(ValueId::new(0)),
            InstrNode::new(Inst::Return {
                values: vec![ValueId::new(0)],
            }),
        ],
    }];
    module
        .try_add_function(function)
        .expect("Module::try_add_function: test fixture");
    module
}

const C_PREFIX: &str = r#"
#include <stdint.h>
#include <stddef.h>
#include <stdio.h>
#include <string.h>
static unsigned long calls, checks;
static int same_byte(unsigned char got, unsigned char expected, size_t offset) {
    ++checks;
    if (got == expected) return 1;
    fprintf(stderr, "EXPECTED_BYTE_MISMATCH offset=%zu got=%02x expected=%02x\n",
            offset, got, expected);
    return 0;
}
"#;

const BODY_DRIVER: &str = r#"
extern void cg_write(void *);
int main(int argc, char **argv) {
    unsigned char expected[] = { EXPECTED_BYTES };
    const int poisoned = argc == 2 && strcmp(argv[1], "--poison") == 0;
    if (argc != 1 && !poisoned) return 96;
    if (poisoned) expected[1] ^= 1;
    const unsigned char fills[] = { 0xa5, 0x00, 0xff };
    for (size_t trial = 0; trial < sizeof fills; ++trial) {
        _Alignas(16) unsigned char arena[16 + sizeof expected + 16];
        memset(arena, fills[trial], sizeof arena);
        cg_write(arena + 16); ++calls;
        for (size_t index = 0; index < sizeof arena; ++index) {
            unsigned char wanted = index < 16 || index >= 16 + sizeof expected
                ? fills[trial] : expected[index - 16];
            if (!same_byte(arena[index], wanted, index)) return 97;
        }
    }
    if (calls != 3 || checks != 3 * (32 + sizeof expected)) return 98;
    printf("NESTED_BYTES_NATIVE_PASS calls=%lu checks=%lu\n", calls, checks);
    return 0;
}
"#;

const GLOBAL_DRIVER: &str = r#"
struct Inner { unsigned char bytes[3]; uint16_t word; };
struct GlobalBytes {
    unsigned char lead;
    struct Inner inner;
    unsigned char rows[2][2];
    const unsigned char *pointer;
    uint16_t tail;
};
_Static_assert(sizeof(struct Inner)==6 && offsetof(struct Inner,word)==4, "inner layout");
_Static_assert(sizeof(struct GlobalBytes)==32 && _Alignof(struct GlobalBytes)==8, "global layout");
_Static_assert(offsetof(struct GlobalBytes,inner)==2 && offsetof(struct GlobalBytes,rows)==8 &&
               offsetof(struct GlobalBytes,pointer)==16 && offsetof(struct GlobalBytes,tail)==24,
               "global field offsets");
extern struct GlobalBytes nested_bytes;
extern void *cg_address(void);
unsigned char external_bytes[9] = { 0xa1, 0xb2, 0xc3, 0xd4, 0xe5, 0xf6, 0x17, 0x28, 0x39 };
int main(int argc, char **argv) {
    unsigned char expected[32] = {
        0x19,0x00,0xff,0x00,0x80,0x00,0x2d,0x4b,
        0x00,0x81,0xfe,0x7f,0x00,0x00,0x00,0x00,
        0,0,0,0,0,0,0,0,0x53,0xa1,0,0,0,0,0,0
    };
    const unsigned char *wanted_pointer = external_bytes + 3;
    memcpy(expected + 16, &wanted_pointer, sizeof wanted_pointer);
    const int poisoned = argc == 2 && strcmp(argv[1], "--poison") == 0;
    if (argc != 1 && !poisoned) return 96;
    if (poisoned) expected[3] ^= 1;
    const unsigned char fills[] = { 0xa5, 0x00, 0xff };
    for (size_t trial = 0; trial < sizeof fills; ++trial) {
        unsigned char arena[16 + sizeof expected + 16];
        memset(arena, fills[trial], sizeof arena);
        const void *actual = cg_address(); ++calls;
        if (actual != &nested_bytes || nested_bytes.pointer != wanted_pointer ||
            *nested_bytes.pointer != 0xd4) return 95;
        memcpy(arena + 16, actual, sizeof expected);
        for (size_t index = 0; index < sizeof arena; ++index) {
            unsigned char wanted = index < 16 || index >= 16 + sizeof expected
                ? fills[trial] : expected[index - 16];
            if (!same_byte(arena[index], wanted, index)) return 97;
        }
    }
    const unsigned char external_expected[] = { 0xa1, 0xb2, 0xc3, 0xd4, 0xe5, 0xf6, 0x17, 0x28, 0x39 };
    for (size_t index = 0; index < sizeof external_expected; ++index)
        if (!same_byte(external_bytes[index], external_expected[index], index)) return 97;
    if (calls != 3 || checks != 201) return 98;
    printf("NESTED_BYTES_NATIVE_PASS calls=%lu checks=%lu\n", calls, checks);
    return 0;
}
"#;

fn compiler(level: OptLevel) -> Compiler {
    Compiler::new_for_target_spec(
        CompilerConfig {
            opt_level: level,
            ..Default::default()
        },
        TargetSpec::parse(native_host::TRIPLE).unwrap(),
    )
    .with_codegen_license(permit_unlicensed())
}

fn validate(module: &Module) {
    let errors = trust_ir_build::validate_module(module);
    assert!(
        errors.is_empty(),
        "canonical TrustIR validation failed: {errors:?}"
    );
}

fn exercise(module: Module, name: &str, driver: &str, checks: usize) {
    validate(&module);
    let directory = fresh_dir::create(&format!("trust-cg-nested-bytes-{name}-"));
    // Keep failure artifacts, including the independent oracle source.
    eprintln!("nested-byte native artifacts: {}", directory.display());
    let driver_path = directory.join("driver.c");
    fs::write(&driver_path, format!("{C_PREFIX}{driver}")).unwrap();
    for level in LEVELS {
        validate(&module);
        let object = compiler(level)
            .compile(&module)
            .unwrap_or_else(|error| panic!("{name} {level:?}: {error}; artifacts={directory:?}"))
            .object_code;
        let object_path = directory.join(format!("{level:?}.o"));
        let binary = directory.join(format!("{level:?}.exe"));
        fs::write(&object_path, object).unwrap();
        let mut link = Command::new("cc");
        link.args(["-std=c11", "-O2", "-Wall", "-Wextra", "-Werror"])
            .arg(&driver_path)
            .arg(&object_path)
            .arg("-o")
            .arg(&binary);
        fs::write(
            directory.join(format!("{level:?}-link.argv")),
            format!("{link:?}\n"),
        )
        .unwrap();
        let linked =
            process::command_output_with_timeout(&mut link, process::codegen_link_timeout())
                .expect("required native C linker must launch");
        retain_output(&directory, &format!("{level:?}-link"), &linked.output);
        assert!(
            !linked.timed_out && linked.output.status.success(),
            "link failed: {directory:?}"
        );
        let run = process::run_executable_with_timeout(&binary, process::codegen_run_timeout())
            .expect("native C oracle must launch");
        retain_output(&directory, &format!("{level:?}-native"), &run.output);
        assert!(
            !run.timed_out && run.output.status.success(),
            "native mismatch: {directory:?}"
        );
        assert_eq!(
            String::from_utf8(run.output.stdout).unwrap(),
            format!("NESTED_BYTES_NATIVE_PASS calls=3 checks={checks}\n")
        );
        let poisoned = process::command_output_with_timeout(
            Command::new(&binary).arg("--poison"),
            process::codegen_run_timeout(),
        )
        .expect("poisoned C oracle must launch");
        retain_output(&directory, &format!("{level:?}-poison"), &poisoned.output);
        assert!(
            !poisoned.timed_out,
            "poisoned oracle timed out: {directory:?}"
        );
        assert_eq!(
            poisoned.output.status.code(),
            Some(97),
            "poison must fail by byte mismatch"
        );
        assert!(
            String::from_utf8_lossy(&poisoned.output.stderr).contains("EXPECTED_BYTE_MISMATCH")
        );
    }
    // Deliberately retain successful artifacts too: exact objects/oracles/logs
    // are useful for independent replay; no qualification is inferred from them.
}

fn retain_output(directory: &Path, name: &str, output: &std::process::Output) {
    fs::write(directory.join(format!("{name}.stdout")), &output.stdout).unwrap();
    fs::write(directory.join(format!("{name}.stderr")), &output.stderr).unwrap();
    fs::write(
        directory.join(format!("{name}.status")),
        format!("{}\n", output.status),
    )
    .unwrap();
}

