/// An enum-typed global with a nested byte-string payload compiles since
/// L05-P5: the object writer renders the direct-tag image (tag word, then each
/// field at the enum image's offset) through the same authority the code path
/// addresses. The byte-exact native evidence for enum globals, including this
/// nested-bytes shape, is `e2e_aarch64_direct_enums.rs`.
#[test]
fn enum_global_nested_bytes_compiles_through_the_direct_tag_image() {
    let mut module = base();
    let ty = direct_enum(&mut module);
    module.globals.push(global(
        "enum_global",
        ty,
        Some(aggregate([
            Constant::Int(1),
            bytes(&[0x00, 0xc3, 0xa9], true),
            Constant::Int(0xe7),
        ])),
    ));
    // Reach the global renderer through the real compiler: an empty module is
    // independently refused before any initializer is examined.
    writer(&mut module, Ty::U8, Constant::Int(0));
    validate(&module);
    for level in LEVELS {
        compiler(level)
            .compile(&module)
            .unwrap_or_else(|error| panic!("{level:?}: enum global must compile: {error}"));
    }
    // A discriminant no variant carries is still refused, by value.
    let mut wrong = base();
    let ty = direct_enum(&mut wrong);
    wrong.globals.push(global(
        "enum_global",
        ty,
        Some(aggregate([
            Constant::Int(2),
            bytes(&[0x00, 0xc3, 0xa9], true),
            Constant::Int(0xe7),
        ])),
    ));
    writer(&mut wrong, Ty::U8, Constant::Int(0));
    assert!(
        !trust_ir_build::validate_module(&wrong).is_empty(),
        "trust-ir's own validator refuses the discriminant first"
    );
    // Every compiler entry consumes that typed verdict before the object
    // writer, so the compile names TrustIR's finding, exactly ...
    let error = compiler(LEVELS[0])
        .compile(&wrong)
        .expect_err("a discriminant no variant carries must be refused");
    assert_eq!(
        error.to_string(),
        "adapter error: trust-ir codegen admission refused the module: global \
         'enum_global': const type mismatch: expected a discriminant of enum DirectBytes, got 2"
    );
    // ... and the writer's own guard is reached through the public conversion,
    // which a caller can run without that admission.
    let error = trust_cg_codegen::compiler::module_object_globals(&wrong)
        .expect_err("the object writer refuses the discriminant by value");
    assert!(error.to_string().contains("names no variant"), "{error}");
}

/// The direct-tag image the object writer renders is the producer's
/// descriptor, checked field by field (`trust_cg_lower::direct_enum`): every
/// field lies inside the image, clear of the tag word and of its siblings.
/// TrustIR's typed admission refuses each misplaced field first on every
/// compiler entry, so the image's own guards are pinned through the public
/// conversion, which a caller can run without that admission.
#[test]
fn enum_global_descriptor_misplacing_a_field_is_refused_by_the_direct_tag_image() {
    for (offsets, admission, image) in [
        (
            // `First`'s byte string at byte 0, over the u8 tag.
            vec![vec![0, 4], vec![1, 4]],
            "expected a direct tag disjoint from every non-ZST field, got tag overlaps variant 0 \
             field 0",
            "EnumDef.layout places variant 0 (`First`) field 0 at bytes 0..3 over the tag word at \
             bytes 0..1",
        ),
        (
            // `Second`'s trailing u8 at byte 5 of the 5-byte image.
            vec![vec![1, 4], vec![1, 5]],
            "expected variant 1 field 1 entirely within size 5, got offset 5, field size 1",
            "EnumDef.layout places variant 1 (`Second`) field 1 (U8, 1 bytes, align 1) at byte 5 \
             of a 5-byte, 1-aligned image, which is out of bounds, misaligned or over-aligned",
        ),
        (
            // `First`'s trailing u8 at byte 3, inside its own byte string.
            vec![vec![1, 3], vec![1, 4]],
            "expected variant 0 fields occupy disjoint byte ranges, got fields 0 and 1 overlap at \
             offsets 1 and 3",
            "EnumDef.layout places variant 0 (`First`) field 1 at bytes 3..4 over its field 0 at \
             bytes 1..4",
        ),
    ] {
        let mut module = base();
        let ty = direct_enum(&mut module);
        module.enums[0]
            .layout
            .as_mut()
            .expect("DirectBytes declares its layout")
            .variant_field_offsets = offsets;
        module.globals.push(global(
            "enum_global",
            ty,
            Some(aggregate([
                Constant::Int(1),
                bytes(&[0x00, 0xc3, 0xa9], true),
                Constant::Int(0xe7),
            ])),
        ));
        writer(&mut module, Ty::U8, Constant::Int(0));
        let error = compiler(LEVELS[0])
            .compile(&module)
            .expect_err("a misplaced descriptor field must be refused");
        assert_eq!(
            error.to_string(),
            format!(
                "adapter error: trust-ir codegen admission refused the module: enum.0 \
                 (DirectBytes) layout: const type mismatch: {admission}"
            )
        );
        let error = trust_cg_codegen::compiler::module_object_globals(&module)
            .expect_err("the direct-tag image refuses the misplaced field");
        assert_eq!(
            error.to_string(),
            format!(
                "object emission failed: trust-ir global enum_global unsupported: unsupported \
                 trust_ir type: [TCG-DIRECT-ENUM] enum EnumId(0) (`DirectBytes`): {image}"
            )
        );
    }
}

/// `Option<[u8; 3]>`-shaped niche enum whose lane is the first payload byte
/// (`None` = 0). The producer declares that byte never 0 in `Some`, as a
/// `NonZeroU8` first element would; the payload bytes are the whole image.
fn niche_bytes_enum(module: &mut Module) -> Ty {
    let payload = byte_array(module, 3);
    module.enums.push(EnumDef {
        origin: None,
        id: EnumId::new(0),
        name: "NicheBytes".into(),
        variants: vec![
            EnumVariant {
                name: "None".into(),
                fields: vec![],
                field_names: vec![],
            },
            EnumVariant {
                name: "Some".into(),
                fields: vec![payload],
                field_names: vec![],
            },
        ],
        discriminants: vec![],
        repr: None,
        layout: Some(EnumLayoutDescriptor {
            encoding: EnumTagEncoding::Niche {
                untagged_variant: 1,
                niche_variants_start: 0,
                niche_variants_end: 0,
                niche_start: 0,
                niche_offset: 0,
                niche_ty: EnumTagRepr::U8,
            },
            size: 3,
            align: 1,
            variant_field_offsets: vec![vec![], vec![0]],
        }),
    });
    Ty::Enum(EnumId::new(0))
}

/// The untagged `Some` of a niche enum is constructed by the niche encoder:
/// its payload bytes ARE the image, with no tag word anywhere.
#[test]
fn native_niche_enum_nested_bytes_o0_through_o3() {
    let mut module = base();
    let ty = niche_bytes_enum(&mut module);
    writer(
        &mut module,
        ty,
        aggregate([Constant::Int(1), bytes(&[0x31, 0x80, 0xff], false)]),
    );
    let driver = BODY_DRIVER.replace("EXPECTED_BYTES", "0x31,0x80,0xff");
    exercise(module, "niche-enum", &driver, 105);
}

/// A `Some` whose first payload byte is the reserved value 0 would read back
/// as `None`, so the niche encoder refuses it at every level.
#[test]
fn niche_enum_nested_bytes_with_a_reserved_lane_is_refused() {
    let mut module = base();
    let ty = niche_bytes_enum(&mut module);
    writer(
        &mut module,
        ty,
        aggregate([Constant::Int(1), bytes(&[0x00, 0x80, 0xff], false)]),
    );
    validate(&module);
    for level in LEVELS {
        let error = compiler(level)
            .compile(&module)
            .expect_err("a reserved niche lane must be refused");
        let diagnostic = error.to_string();
        assert!(
            diagnostic.contains("[TCG-NICHE-ENUM]") && diagnostic.contains("reserved niche value"),
            "{level:?}: {diagnostic}"
        );
    }
}

/// This file's fixtures are hand-built and carry no codegen license
/// (`body_gate: None`), which trust-cg REFUSES by default (roadmap WS7.5,
/// decision gate DG-73). Its compiles state `Permit` explicitly, so none of
/// them passes because it was silently refused.
fn permit_unlicensed() -> trust_cg_lower::CodegenLicensePolicy {
    trust_cg_lower::CodegenLicensePolicy::default()
        .with_unlicensed(trust_cg_lower::UnlicensedBodyPolicy::Permit)
}
